  static DataGridView Grid(bool readOnly){return new DataGridView{Dock=DockStyle.Fill,ReadOnly=readOnly,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AllowUserToResizeRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.None,SelectionMode=readOnly?DataGridViewSelectionMode.FullRowSelect:DataGridViewSelectionMode.CellSelect,MultiSelect=false,BackgroundColor=SystemColors.Window,BorderStyle=BorderStyle.FixedSingle,ClipboardCopyMode=DataGridViewClipboardCopyMode.EnableAlwaysIncludeHeaderText,ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.AutoSize};}
