  bool InDragBox(Point p){var size=SystemInformation.DragSize;return new Rectangle(dragStart.X-size.Width/2,dragStart.Y-size.Height/2,size.Width,size.Height).Contains(p);}
  void AllocationDragOver(object sender,DragEventArgs e){bool accepted=e.Data.GetDataPresent(typeof(FontCatalogEntry));var move=e.Data.GetData(typeof(AllocationDrag)) as AllocationDrag;accepted|=move!=null&&move.Window==this;e.Effect=accepted?DragDropEffects.Move:DragDropEffects.None;var pt=allocated.PointToClient(new Point(e.X,e.Y));int first=allocated.FirstDisplayedScrollingRowIndex;if(first>=0&&pt.Y<allocated.ColumnHeadersHeight+20&&first>0)allocated.FirstDisplayedScrollingRowIndex=first-1;else if(first>=0&&pt.Y>allocated.Height-20&&first<allocated.RowCount-1)allocated.FirstDisplayedScrollingRowIndex=first+1;}
  internal void SelectAllocation(int number){requestedSlot=number;if(allocated.RowCount>number&&number>=0){allocated.CurrentCell=allocated.Rows[number].Cells[1];allocated.FirstDisplayedScrollingRowIndex=number;ShowAfm();}}
  internal void SetSnapshot(FontAllocationSnapshot next){if(dirty){if(snapshot!=null&&snapshot.Key==next.Key&&!Object.ReferenceEquals(snapshot.Fonts,next.Fonts)){snapshot.Fonts=next.Fonts;PopulateAvailable(next.Fonts);HighlightDuplicates();if(previews.Checked)QueuePreviews();}status.Text="Files/catalog updated in background. Staged edits preserved; Reload if a PSC changed outside this window.";return;}if(snapshot!=null&&snapshot.Key==next.Key&&snapshot.Stamp==next.Stamp)return;int selected=allocated.CurrentCell==null?requestedSlot:allocated.CurrentCell.RowIndex;snapshot=next;rows=next.Allocations.Select(r=>r.Copy()).ToArray();loading=true;try{allocated.Rows.Clear();foreach(var row in rows)allocated.Rows.Add(row.Number.ToString("00"),row.Name,State(row));PopulateAvailable(next.Fonts);foreach(var row in rows)allocated.Rows[row.Number].Cells[1].ToolTipText=row.Path+"\n"+row.Error;int duplicates=rows.Where(r=>r.Name.Length>0).GroupBy(r=>r.Name,StringComparer.Ordinal).Count(g=>g.Count()>1);foreach(var group in rows.Where(r=>r.Name.Length>0).GroupBy(r=>r.Name,StringComparer.Ordinal).Where(g=>g.Count()>1))foreach(var row in group)allocated.Rows[row.Number].ErrorText="Existing duplicate allocation; clear or change one before saving.";save.Enabled=true;status.Text=(duplicates>0?duplicates+" existing duplicate FontNames; resolve before saving. ":"")+next.Fonts.Length+" distinct Type 1 files; "+rows.Count(r=>r.Name.Length>0)+" allocations. "+(next.Errors.Length==0?"":next.Errors.Length+" resource errors (see row details).");}finally{loading=false;}HighlightDuplicates();SelectAllocation(selected);ShowAfm();if(previews.Checked)QueuePreviews();}
  void PopulateAvailable(FontCatalogEntry[] fonts){available.Rows.Clear();foreach(var font in fonts){int i=available.Rows.Add(font.Name,font.Family,font.Version,null);available.Rows[i].Tag=font;foreach(DataGridViewCell cell in available.Rows[i].Cells)cell.ToolTipText=font.Description+"\nFile: "+font.Path+"\nMatching AFMs: "+font.Afms.Length;}}
  static string State(FontAllocation row){return row.Error.Length>0?"Invalid PSC":row.Name.Length==0?"Empty":row.Bytes==null?"Generate AFM":"PSC";}
  void RenderRows(){loading=true;try{foreach(var row in rows){allocated.Rows[row.Number].Cells[1].Value=row.Name;allocated.Rows[row.Number].Cells[2].Value=State(row);}}finally{loading=false;}HighlightDuplicates();ShowAfm();}
  void Assign(int target,FontCatalogEntry font,int? from){if(rows==null||font==null||font.Name.Length==0)return;try{CommitAfm();}catch(Exception error){MessageBox.Show(this,error.Message,"Selected AFM",MessageBoxButtons.OK,MessageBoxIcon.Error);return;}FontAllocationCatalog.Assign(rows,target,font,from);dirty=true;RenderRows();SelectAllocation(target);status.Text="Staged allocation changes. Save writes PSCs and reusable font-named copies; MUS files are unchanged.";}
  void ValidateFont(object sender,DataGridViewCellValidatingEventArgs e){if(loading||rows==null||e.ColumnIndex!=1)return;string name=Convert.ToString(e.FormattedValue).Trim();if(name==rows[e.RowIndex].Name)return;if(name.Length==0){rows[e.RowIndex].Name="";rows[e.RowIndex].Bytes=null;rows[e.RowIndex].Error="";rows[e.RowIndex].Afm="";rows[e.RowIndex].FontPath="";dirty=true;BeginInvoke(new Action(RenderRows));return;}if(rows.Any(r=>r.Number!=e.RowIndex&&r.Name==name)){allocated.Rows[e.RowIndex].ErrorText="Already allocated. Drag its allocation to move or swap it.";e.Cancel=true;return;}var fonts=snapshot.Fonts.Where(f=>f.Name==name).ToArray();if(fonts.Length!=1){allocated.Rows[e.RowIndex].ErrorText=fonts.Length==0?"FontName not in the selected Type 1 folder.":"Several versions exist. Drag the intended font row from the available table.";e.Cancel=true;return;}FontAllocationCatalog.Assign(rows,e.RowIndex,fonts[0],null);dirty=true;BeginInvoke(new Action(RenderRows));}
  protected override void OnVisibleChanged(EventArgs e){base.OnVisibleChanged(e);if(Visible)HighlightDuplicates();}
  void HighlightDuplicates(){if(rows==null)return;var duplicates=new HashSet<string>(rows.Where(r=>r.Name.Length>0).GroupBy(r=>r.Name,StringComparer.Ordinal).Where(g=>g.Count()>1).Select(g=>g.Key),StringComparer.Ordinal);foreach(DataGridViewRow row in allocated.Rows){bool duplicate=duplicates.Contains(rows[row.Index].Name);row.DefaultCellStyle.BackColor=duplicate?NativeWindowsColors.DuplicateFontColor:Color.Empty;row.DefaultCellStyle.SelectionBackColor=duplicate?ControlPaint.Dark(NativeWindowsColors.DuplicateFontColor,.08f):Color.Empty;row.DefaultCellStyle.SelectionForeColor=duplicate?Color.Black:Color.Empty;}var versions=new HashSet<string>(available.Rows.Cast<DataGridViewRow>().Select(r=>r.Tag as FontCatalogEntry).Where(f=>f!=null).GroupBy(f=>f.Name,StringComparer.Ordinal).Where(g=>g.Count()>1).Select(g=>g.Key),StringComparer.Ordinal);foreach(DataGridViewRow row in available.Rows){var font=row.Tag as FontCatalogEntry;bool duplicate=font!=null&&(duplicates.Contains(font.Name)||versions.Contains(font.Name));row.DefaultCellStyle.BackColor=duplicate?NativeWindowsColors.DuplicateFontColor:Color.Empty;row.DefaultCellStyle.SelectionBackColor=duplicate?ControlPaint.Dark(NativeWindowsColors.DuplicateFontColor,.08f):Color.Empty;row.DefaultCellStyle.SelectionForeColor=duplicate?Color.Black:Color.Empty;}}
  void ShowAfm(){if(loading||afm==null)return;afmSlot=rows==null||allocated.CurrentCell==null?-1:allocated.CurrentCell.RowIndex;var row=afmSlot<0?null:rows[afmSlot];afm.Text=row==null?"":row.Afm;afm.Enabled=row!=null&&row.Name.Length>0;tips.SetToolTip(afm,row==null||row.Bytes==null?null:row.Afm.Length==0?"No unique AFM was found for this allocation.":row.AfmMatchesInstalled?"This AFM reproduces the installed PSC metrics.":"This AFM has the allocated FontName. The installed PSC has different metrics.");}
  void TryCommitAfm(){try{CommitAfm();}catch(Exception error){MessageBox.Show(this,error.Message,"Selected AFM",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
  void CommitAfm(){if(loading||rows==null||afmSlot<0||!afm.Enabled)return;var row=rows[afmSlot];string value=afm.Text.Trim();if(value==row.Afm)return;if(value.Length>0){string input=File.ReadAllText(value);if(FontconvPscModel.FontName(input)!=row.Name)throw new InvalidDataException("The AFM FontName does not match the selected allocation.");if(row.FontPath.Length==0){var fonts=snapshot.Fonts.Where(f=>f.Name==row.Name).ToArray();if(fonts.Length!=1)throw new InvalidDataException("Drag the intended Type 1 version onto this slot first.");row.FontPath=fonts[0].Path;}}row.Afm=value;row.AfmMatchesInstalled=false;row.Bytes=null;dirty=true;allocated.Rows[row.Number].Cells[2].Value=State(row);}
  internal void Saved(string message){dirty=false;snapshot=null;status.Text=message;}
  internal void LoadFailed(string message){status.Text="Font catalog: "+message;}
  void QueuePreviews(){if(snapshot==null||previewRunning||IsDisposed)return;var fonts=snapshot.Fonts.Where(f=>!images.ContainsKey(f.Hash)&&!failedPreviews.Contains(f.Hash)).ToArray();if(fonts.Length==0){ApplyPreviews();return;}previewRunning=true;Task.Run(()=>{foreach(var font in fonts){Bitmap image=null;string error=null;try{image=Preview(font);}catch(Exception e){error=e.Message;}if(IsDisposed){if(image!=null)image.Dispose();break;}var bitmap=image;var failure=error;try{BeginInvoke(new Action(()=>{if(IsDisposed){if(bitmap!=null)bitmap.Dispose();return;}if(bitmap!=null)images[font.Hash]=bitmap;else{failedPreviews.Add(font.Hash);foreach(DataGridViewRow row in available.Rows)if(((FontCatalogEntry)row.Tag).Hash==font.Hash)row.Cells["Preview"].ToolTipText="No Type 1 preview: "+failure;}ApplyPreviews();}));}catch(InvalidOperationException){if(bitmap!=null)bitmap.Dispose();break;}}}).ContinueWith(t=>{if(!IsDisposed)try{BeginInvoke(new Action(()=>{previewRunning=false;if(previews.Checked)QueuePreviews();}));}catch(InvalidOperationException){}});}
  void ApplyPreviews(){foreach(DataGridViewRow row in available.Rows){Bitmap image;if(images.TryGetValue(((FontCatalogEntry)row.Tag).Hash,out image))row.Cells["Preview"].Value=image;}}
  static Bitmap Preview(FontCatalogEntry entry){var font=new Type1Outline(entry.Path);using(var combined=new GraphicsPath()){float x=0;foreach(char c in entry.Name.Take(60)){float advance;using(var glyph=font.Character(c,out advance)){using(var m=new Matrix(1,0,0,1,x,0))glyph.Transform(m);combined.AddPath(glyph,false);}x+=advance;}if(combined.PointCount==0)throw new InvalidDataException("No outline for this font name.");var bounds=combined.GetBounds();var image=new Bitmap(600,60);try{using(var g=Graphics.FromImage(image)){g.Clear(Color.White);g.SmoothingMode=SmoothingMode.AntiAlias;float scale=Math.Min(590/Math.Max(1,bounds.Width),50/Math.Max(1,bounds.Height));using(var m=new Matrix(scale,0,0,-scale,5-bounds.Left*scale,5+bounds.Bottom*scale))combined.Transform(m);g.FillPath(Brushes.Black,combined);}return image;}catch{image.Dispose();throw;}}}
